<?php

namespace Ecompetence\EcompetenceBundle\Repository;

/**
 * Cv_directiongleRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class Cv_directiongleRepository extends \Doctrine\ORM\EntityRepository
{
    public function findAllOrderedByName()
{
    return $this->createQueryBuilder('d')
        ->orderBy('d.libdirectiongle', 'ASC') 
        ;
}
}
